<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { sleepMetrics, sleepStages, today, useDreamJourney, winddown } from '../composables/useDreamJourney'
import { useJourneyUi } from '../composables/useJourneyUi'
const route=useRoute(),router=useRouter(),{journals,plan,rituals,refresh,commit}=useDreamJourney(),{toast,notify,save}=useJourneyUi()
const path=computed(()=>route.path),step=ref(0),stage=ref(0),editing=ref(false),selected=ref(null)
const form=ref({date:today(),bed:'22:30',asleep:'23:00',wake:'07:00',up:'07:15',noSleep:false,awakenings:0,awakeMinutes:0,quality:'一般',body:[],emotion:[],note:''})
const times=[{key:'bed',title:'昨晚，什么时候上床？',hint:'先记下躺到床上的大致时刻，不用特别精确。'},{key:'asleep',title:'大概什么时候睡着？',hint:'凭印象估计就好，不需要在夜里看钟。'},{key:'wake',title:'今天，什么时候醒来？',hint:'最后一次醒来，准备开始这一天的时刻。'},{key:'up',title:'什么时候真正起床？',hint:'把身体交给白天，慢慢开始新的一天。'}]
const latest=computed(()=>selected.value||journals.value[0]),metric=computed(()=>latest.value?sleepMetrics(latest.value):null),dates=computed(()=>new Set(journals.value.map(j=>j.date))),growth=computed(()=>Math.min(30,dates.value.size)),bedtime=ref(plan.value.bedtime),wake=ref(plan.value.wake),started=ref(plan.value.started||today())
const duration=n=>Math.floor(n/60)+' 小时 '+n%60+' 分',flip=(arr,item)=>arr.includes(item)?arr.filter(x=>x!==item):[...arr,item]
const done=computed(()=>rituals.value[today()]||[]),currentStage=computed(()=>sleepStages[stage.value]),completed=computed(()=>plan.value.completed||[])
function before(n){const [h,m]=plan.value.bedtime.split(':').map(Number);const v=(h*60+m-n+1440)%1440;return String(Math.floor(v/60)).padStart(2,'0')+':'+String(v%60).padStart(2,'0')}
async function savePlan(){if(!bedtime.value||!wake.value||!started.value)return notify('先选好作息时刻和开始日期');await save(commit,'plan',{...plan.value,bedtime:bedtime.value,wake:wake.value,started:started.value},'作息心愿已保存，可随时调整')}
async function saveDiary(){const f=form.value,m=sleepMetrics(f);if(!f.date||f.date>today())return notify('请选择今天或之前的晨起日期');if(m.inBed<=0||m.inBed>1200)return notify('请检查上床和起床时刻');if(!f.noSleep&&(m.latency+m.linger+Number(f.awakeMinutes)>m.inBed||m.sleep+m.latency+m.linger>m.inBed))return notify('时刻先后或清醒时长不一致，请回到前面检查');if(f.awakenings<0||f.awakenings>30||f.awakeMinutes<0||f.awakeMinutes>1200)return notify('请检查夜间清醒次数和时长');const entry={...f,id:Date.now()};if(await save(commit,'journals',[entry,...journals.value.filter(j=>j.date!==f.date)],'这一晚已留下，星球也多了一点生机')){selected.value=entry;editing.value=false;step.value=0}}
function begin(){const existing=journals.value.find(j=>j.date===today());form.value=existing?{...existing,body:[...existing.body],emotion:[...existing.emotion]}:{...form.value,date:today()};step.value=0;editing.value=true}
// Keep empty nights empty; only saved local receipts appear in the seven-night view.
const weekNights=computed(()=>Array.from({length:7},(_,i)=>{const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()-6+i);const date=d.toLocaleDateString('sv-SE');return{date,label:d.toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'}),weekday:d.toLocaleDateString('zh-CN',{weekday:'short'}),entry:journals.value.find(j=>j.date===date)}}))
const weekCount=computed(()=>weekNights.value.filter(n=>n.entry).length)
function openNight(n){if(n.entry){selected.value=n.entry;return}form.value={date:n.date,bed:'22:30',asleep:'23:00',wake:'07:00',up:'07:15',noSleep:false,awakenings:0,awakeMinutes:0,quality:'一般',body:[],emotion:[],note:''};step.value=0;editing.value=true}
function quickFeeling(feeling){begin();form.value.body=flip(form.value.body,feeling);step.value=4;notify('已带入醒来感受，完成后收下这一晚即可保存')}
async function checkTask(i){await save(commit,'plan',{...plan.value,completed:flip(completed.value,stage.value+'-'+i)})}
async function checkRitual(key){await save(commit,'rituals',{...rituals.value,[today()]:flip(done.value,key)})}
const days=computed(()=>Array.from({length:30},(_,i)=>{const d=new Date((plan.value.started||today())+'T12:00:00');d.setDate(d.getDate()+i);return{day:i+1,date:d.toLocaleDateString('sv-SE')}}))
const routine=[{before:70,duration:30,title:'洗漱与日常护理',text:'温暖灯光、舒服睡衣，把工作通知放到明天。'},{before:40,duration:30,title:'放松、轻音乐或纸质书',text:'选一件让自己放缓的事，不必每项都完成。'},{before:10,duration:10,title:'安放情绪，留下种子',text:'写下一句话，把计时和期待轻轻放下。'}]
onMounted(refresh)
</script>
<template>
<div class="journey">
<p class="j-notice"><span class="j-dot"></span>手动记录 · 数据保存在当前账号；未连接手环或医疗设备。</p>
<template v-if="path==='/dream/sleep-diary'">
 <section v-if="!editing" class="j-panel diary-invite"><div><h2>把昨夜，轻轻交给今天</h2><p>从四个大致时刻开始，再留下醒来时的感受。</p><button class="j-primary" @click="begin">{{dates.has(today())?'修改今天的睡眠日记':'留下今天的睡眠日记'}}</button></div><img src="/dream-rooms/rest.png" alt="安静的睡前房间"></section>
 <template v-if="!editing">
 <section class="j-panel diary-week"><div class="j-between"><div><h2>近七晚，慢慢留下自己的节律</h2><p class="j-muted">点亮的一天，是你真实留下的夜晚。空着的一天，也可以回来补记。</p></div><span class="j-tag">已留下 {{weekCount}} / 7 晚</span></div><div class="diary-week-grid"><button v-for="n in weekNights" :key="n.date" :class="{'has-night':n.entry,'night-current':latest?.date===n.date}" :aria-label="n.date+(n.entry?' 查看睡眠回执':' 补记这一晚')" :aria-pressed="latest?.date===n.date" @click="openNight(n)"><small>{{n.weekday}}</small><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M27 7a14 14 0 1 0 7 23A15 15 0 0 1 27 7Z"/><circle cx="12" cy="9" r="1.5"/></svg><strong>{{n.label}}</strong><span>{{n.entry?n.entry.quality:'待留光'}}</span></button></div><p class="j-help">按晨起日期归档 · {{weekCount?'点击已记录的日期，在下方回看那一晚。':'从今天开始，第一份回执会在这里亮起。'}}</p></section>
 <div class="diary-pair">
 <section class="j-panel"><h2>此刻，身体想说什么？</h2><p>不必先想清楚昨夜发生了什么，选一个最接近醒来时的感受。</p><div class="j-row"><button v-for="f in ['放松','正常','疲惫','不适']" :key="f" @click="quickFeeling(f)">{{f}}</button></div><p class="j-help">选择后进入晨起回执，可继续补充、修改，再保存。</p><div class="diary-note"><h3>给自己的一句提醒</h3><p>记不清入睡时刻也没关系，凭印象留下大致时间。夜里不必为了记录反复看钟。</p></div></section>
 <section class="j-panel"><h2>让今夜，多一点从容</h2><p>先从一件愿意做的小事开始，不必把睡前变成任务。</p><div class="diary-actions"><button @click="router.push('/dream/wind-down')"><span><strong>给夜晚留一段缓冲</strong><small>调暗灯光、放下通知，按自己的节奏收尾</small></span><span aria-hidden="true">→</span></button><button @click="router.push('/dream/relax')"><span><strong>让紧绷的身体松一点</strong><small>跟随一段温柔的呼吸与放松引导</small></span><span aria-hidden="true">→</span></button><button @click="router.push('/dream/sleep-plan')"><span><strong>找到愿意坚持的节律</strong><small>留一个作息心愿，随时都可以调整</small></span><span aria-hidden="true">→</span></button></div></section>
 </div>
 </template>
 <section v-if="editing" class="j-panel diary-wizard"><div class="j-between"><small>晨起回执 · {{step+1}} / 6</small><button @click="editing=false">稍后继续</button></div><div class="sleep-progress"><span :style="{transform:'scaleX('+((step+1)/6)+')'}"></span></div>
 <template v-if="step<4"><h2>{{times[step].title}}</h2><p class="j-muted">{{times[step].hint}}</p><label v-if="step===0" class="clock-picker">这份日记的晨起日期<input v-model="form.date" type="date" :max="today()"></label><label class="clock-picker"><span class="j-sr">{{times[step].title}}</span><input v-model="form[times[step].key]" type="time" :disabled="step===1&&form.noSleep"></label><label v-if="step===1" class="j-check"><input v-model="form.noSleep" type="checkbox"><span>这一晚，感觉整夜没有睡着</span></label></template>
 <template v-else-if="step===4"><h2>醒来后，身体是什么样的？</h2><fieldset><legend>这一晚的主观感受</legend><div class="j-row"><button v-for="q in ['很差','不太好','一般','还不错','很好']" :key="q" :class="{'j-selected':form.quality===q}" @click="form.quality=q">{{q}}</button></div></fieldset><fieldset class="j-section-gap"><legend>身体的信号 · 可多选</legend><div class="j-row"><button v-for="b in ['放松','正常','疲惫','生病','疼痛','腹胀','饥饿','不适','精力过剩']" :key="b" :aria-pressed="form.body.includes(b)" :class="{'j-selected':form.body.includes(b)}" @click="form.body=flip(form.body,b)">{{b}}</button></div></fieldset><fieldset class="j-section-gap"><legend>睡前的心情 · 可多选</legend><div class="j-row"><button v-for="e in ['平静','倦怠','愉快','兴奋','生气','低落','悲伤','烦躁','焦虑','恐惧']" :key="e" :aria-pressed="form.emotion.includes(e)" :class="{'j-selected':form.emotion.includes(e)}" @click="form.emotion=flip(form.emotion,e)">{{e}}</button></div></fieldset></template>
 <template v-else><h2>最后，留一点夜里的细节</h2><div class="j-grid"><label>夜间醒来次数<input v-model.number="form.awakenings" type="number" min="0" max="30"></label><label>清醒合计约几分钟<input v-model.number="form.awakeMinutes" type="number" min="0" max="1200"></label></div><label class="j-section-gap">可选的一句感受<textarea v-model="form.note" maxlength="200" rows="2" placeholder="比如：醒来时窗外的光很柔和。"></textarea></label><p class="j-help">同一晨起日期保留一份日记，再保存会更新当日内容。</p></template>
 <div class="j-between j-section-gap"><button :disabled="step===0" @click="step--">上一页</button><button v-if="step<5" class="j-primary" @click="step<4&&!form[times[step].key]?notify('先选一个大致时刻'):step++">继续</button><button v-else class="j-primary" @click="saveDiary">收下这一晚</button></div></section>
 <section v-if="latest&&!editing" class="j-panel"><div class="j-between"><div><small>{{latest.date}} · 晨起回执</small><h2>这一晚，身体留下的信号</h2></div><span class="j-tag">{{latest.quality}}</span></div><div class="j-metrics"><div v-for="m in [{name:'在床时长',value:duration(metric.inBed)},{name:'估计睡眠',value:duration(metric.sleep)},{name:'睡眠占在床时间',value:metric.efficiency+'%'},{name:'入睡等待',value:metric.latency+' 分钟'},{name:'夜间醒来',value:latest.awakenings+' 次'},{name:'夜间清醒合计',value:latest.awakeMinutes+' 分钟'},{name:'醒来后停留',value:metric.linger+' 分钟'}]" :key="m.name" class="j-metric"><small>{{m.name}}</small><strong>{{m.value}}</strong></div></div><div class="sleep-clock-row"><span v-for="t in times" :key="t.key"><small>{{({bed:'上床',asleep:'睡着',wake:'醒来',up:'起床'})[t.key]}}</small><b>{{latest.noSleep&&t.key==='asleep'?'整夜未睡':latest[t.key]}}</b></span></div><div class="j-row j-section-gap"><span v-for="b in latest.body" :key="b" class="j-tag blue">{{b}}</span><span v-for="e in latest.emotion" :key="e" class="j-tag">{{e}}</span></div><p>{{latest.note}}</p><small>由手动时刻估算，不是设备监测结果，也不是睡眠质量诊断。</small></section>
 <section v-if="journals.length&&!editing" class="j-panel"><h3>走过的夜晚</h3><div class="j-row"><button v-for="j in journals" :key="j.id" :class="{'j-selected':latest?.id===j.id}" @click="selected=j">{{j.date}} · {{j.quality}}</button></div></section>
</template>
<template v-else-if="path==='/dream/sleep-plan'">
 <section class="j-panel"><h2>让习惯生长，而不是催促睡眠</h2><p>五个阶段，按自己的节奏走。周数只是参考。</p><div class="j-grid"><label>心愿入睡时刻<input v-model="bedtime" type="time"></label><label>心愿起床时刻<input v-model="wake" type="time"></label></div><label class="j-section-gap">从哪一天开始<input v-model="started" type="date"></label><div class="j-between j-section-gap"><button class="j-primary" @click="savePlan">保存我的节律</button><small>{{dates.size}} 天真实记录 · {{completed.length}} 个小行动</small></div></section>
 <div class="j-wide-grid j-section-gap"><aside class="j-panel stage-nav"><button v-for="(s,i) in sleepStages" :key="s.name" :class="{'j-selected':stage===i}" @click="stage=i"><span>{{String(i+1).padStart(2,'0')}}</span><span>{{s.name}}<small>{{s.span}}</small></span></button></aside><section class="j-panel"><small>{{currentStage.span}} · 可自行延长</small><h2>{{currentStage.name}}</h2><p>{{currentStage.intro}}</p><label v-for="(task,i) in currentStage.tasks" :key="task" class="j-check"><input type="checkbox" :checked="completed.includes(stage+'-'+i)" @change="checkTask(i)"><span>{{task}}</span></label><div class="j-rule"></div><h3>这一阶段，想告诉你</h3><p>{{currentStage.lesson}}</p><div class="j-row"><button @click="router.push('/dream/sleep-diary')">留下睡眠日记</button><button @click="router.push('/dream/relax')">做一段放松练习</button></div></section></div>
</template>
<template v-else-if="path==='/dream/wind-down'">
 <section class="j-panel"><div class="j-between"><div><h2>今晚 {{plan.bedtime}}，给自己一个温柔的收尾</h2><p>按你的心愿时刻自动倒推。流程是邀请，可以只选适合的部分。</p></div><button @click="router.push('/dream/sleep-plan')">调整作息</button></div><div class="routine-band"><article v-for="r in routine" :key="r.title"><small>{{before(r.before)}} — {{before(r.before-r.duration)}} · {{r.duration}} 分钟</small><h3>{{r.title}}</h3><p>{{r.text}}</p></article></div><small>共 70 分钟，从 {{before(70)}} 开始，到 {{plan.bedtime}} 结束。</small></section>
 <section v-for="(s,index) in winddown" :key="s.before" class="j-panel"><div class="j-between"><div><small>{{before(s.before)}} · 睡前 {{s.before===10?'最后 10 分钟':s.before/60+' 小时'}}</small><h2>{{s.title}}</h2></div><span class="j-tag">{{s.items.filter((_,i)=>done.includes(index+'-'+i)).length}} / {{s.items.length}}</span></div><label v-for="(item,i) in s.items" :key="item" class="j-check"><input type="checkbox" :checked="done.includes(index+'-'+i)" @change="checkRitual(index+'-'+i)"><span>{{item}}</span></label></section><div class="j-row j-section-gap"><button class="j-primary" @click="router.push('/dream/cues')">给今夜留一颗种子</button><button @click="router.push('/dream/bedtime-stories')">听一段睡前故事</button></div>
</template>
<template v-else>
 <section class="j-panel planet-stage"><div class="planet-sky" aria-hidden="true"><svg viewBox="0 0 600 360"><defs><radialGradient id="journeyPlanet"><stop stop-color="#faf5e8"/><stop offset=".7" stop-color="#c7d9d9"/><stop offset="1" stop-color="#acb8cc"/></radialGradient></defs><g fill="#c7bed8"><circle v-for="i in 24" :key="i" :cx="30+(i*79)%540" :cy="20+(i*53)%280" :r="i%3===0?2.5:1.2"/></g><ellipse cx="300" cy="195" rx="230" ry="55" fill="none" stroke="#d3c9df" stroke-width="2" transform="rotate(-17 300 195)"/><circle cx="300" cy="185" r="118" fill="url(#journeyPlanet)"/><path d="M199 180q45-35 93 6t110-10 M207 222q65-37 157 5" fill="none" stroke="#b0c6ba" stroke-width="15" opacity=".65"/><g v-for="i in Math.min(growth,18)" :key="i" :transform="'translate('+(218+i*37%160)+' '+(135+i*29%110)+')'"><path d="M0 12V-9 M0 2q-15-16-13-18Q2-16 0 2 M0-3q14-15 16-12Q17-3 0-3" fill="#8ba98e" stroke="#829d87"/><circle v-if="growth>12" cy="-12" r="5" fill="#e2bbbe"/></g></svg></div><div class="planet-copy"><span class="j-tag">30 天 · 温柔生长计划</span><h2>{{growth===0?'第一束微光，还在等你':growth<10?'小小的绿意，开始生长':growth<22?'星球已经长出自己的花园':'被照顾的夜晚，正在开花'}}</h2><p>已留下 {{growth}} 个不同日期的睡眠回执。漏记也没关系，不会扣除已经长出的绿意。</p><button class="j-primary" @click="router.push('/dream/sleep-diary')">{{dates.has(today())?'看看今天的回执':'给星球留下一晚'}}</button><div class="sleep-progress"><span :style="{transform:'scaleX('+growth/30+')'}"></span></div><small>记录旅程 {{Math.round(growth/30*100)}}% · 不是健康评分</small></div></section>
 <section class="j-panel"><div class="j-between"><h3>三十天，不必连成一条直线</h3><small>开始于 {{plan.started||today()}}</small></div><div class="planet-days"><button v-for="d in days" :key="d.date" :class="{'j-selected':dates.has(d.date)}" :aria-label="d.date+(dates.has(d.date)?' 已记录':' 未记录')" @click="notify(d.date+(dates.has(d.date)?' 已留下回执':' 还没有回执，按自己的节奏来'))"><span>{{String(d.day).padStart(2,'0')}}</span><small>{{dates.has(d.date)?'已留光':'待生长'}}</small></button></div></section><div class="j-grid j-section-gap"><section class="j-panel"><h3>心事，也有安放的地方</h3><p>焦虑、孤单、睡不着，都不必一个人藏着。</p><button @click="router.push('/dream/tree-hole')">去情绪树洞</button></section><section class="j-panel" style="margin-top:0"><h3>先照顾此刻</h3><p>找一个轻松的小活动，让注意力慢慢落地。</p><button @click="router.push('/dream/tree-hole#calm-tools')">去情绪树洞，照顾此刻</button></section></div>
</template><div v-if="toast" class="j-toast" role="status">{{toast}}</div>
</div>
</template>
<style scoped>
.diary-week-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:12px;margin:24px 0 14px}.diary-week-grid button{display:flex;flex-direction:column;align-items:center;gap:8px;padding:18px 6px;background:#f7f8fb;border:1px solid #e7e7ef;border-radius:18px;color:#7c7b91;min-height:156px}.diary-week-grid svg{width:38px;height:38px;fill:#e3e5ef;stroke:#a5a6bd;stroke-width:1.2}.diary-week-grid .has-night{background:#f1edf7;color:#65537d}.diary-week-grid .has-night svg{fill:#b8a6d0;stroke:#87709e}.diary-week-grid .night-current{outline:2px solid #a293b9;outline-offset:2px}.diary-week-grid button span{font-size:12px}.diary-week-grid button strong{font-size:14px;font-weight:500;font-variant-numeric:tabular-nums}.diary-pair{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px}.diary-pair>.j-panel{margin-top:0}.diary-note{margin-top:25px;padding-top:20px;border-top:1px solid #ebe6f0}.diary-note h3{font-size:16px}.diary-note p{font-size:14px}.diary-actions{display:grid;gap:8px;margin-top:20px}.diary-actions button{display:flex;justify-content:space-between;text-align:left;gap:12px;padding:15px!important;background:#f6f5f9!important}.diary-actions strong{display:block;font-size:14px;font-weight:500}.diary-actions small{display:block;font-size:12px;margin-top:5px;white-space:normal}.diary-week-grid button:focus-visible,.diary-actions button:focus-visible{outline:2px solid #8b7cab;outline-offset:3px}@media(max-width:760px){.diary-pair{grid-template-columns:1fr}.diary-week-grid{gap:7px;grid-template-columns:repeat(4,minmax(0,1fr))}.diary-week-grid button{padding:12px 4px;min-height:135px}.diary-week .j-between{align-items:flex-start;flex-wrap:wrap}.diary-week h2{font-size:20px}}
